import { MARKET_KINDS } from '../types/domain';
import type { MarketKind, MarketSelection } from '../types/domain';
import { defaultLiveForm, defaultOddsForm, marketKindConfig } from './forms';
import type { LiveFormState, OddsFormState } from './forms';

/**
 * Filling eight fields by hand while a match is running is the slow part of using this app, so the
 * whole form can be pasted in as one JSON object instead.
 *
 * The shape is deliberately flat and forgiving rather than mirroring the API: it is typed by a person
 * on a phone with a stats screen open, not generated by a machine. Field names accept the obvious
 * aliases, selections accept Romanian as well as English, and every rejection names the field it is
 * unhappy about — a silent default here would size a stake against the wrong side of a market.
 */

/** What a successful parse produces: the two form states, ready to drop into React state. */
export interface QuickImportResult {
    odds: OddsFormState;
    live: LiveFormState;
    bankroll: number | null;
}

export class QuickImportError extends Error {
    constructor(message: string) {
        super(message);
        this.name = 'QuickImportError';
    }
}

/** The example shown in the panel — real numbers, so it works if pasted unchanged. */
export const QUICK_IMPORT_EXAMPLE = `{
  "match": "Barcelona - Racing Club",
  "minute": 36,
  "xgHome": 2.38,
  "xgAway": 0.30,
  "goalsHome": 3,
  "goalsAway": 1,
  "market": "TotalGoals",
  "selection": "Over",
  "line": 6.5,
  "odds": 1.91,
  "siblingOdds": [1.91],
  "bankroll": 263
}`;

// --- Field aliases ----------------------------------------------------------

const MARKET_ALIASES: Record<string, MarketKind> = {
    totalgoals: 'TotalGoals',
    total: 'TotalGoals',
    totals: 'TotalGoals',
    goluri: 'TotalGoals',
    ou: 'TotalGoals',
    nextgoal: 'NextGoal',
    next: 'NextGoal',
    primulgol: 'NextGoal',
    bothteamstoscore: 'BothTeamsToScore',
    btts: 'BothTeamsToScore',
    gg: 'BothTeamsToScore',
    ggng: 'BothTeamsToScore',
    moneyline1x2: 'Moneyline1X2',
    moneyline: 'Moneyline1X2',
    '1x2': 'Moneyline1X2',
    result: 'Moneyline1X2',
    rezultat: 'Moneyline1X2',
    handicap: 'Handicap',
    hcp: 'Handicap',
};

const SELECTION_ALIASES: Record<MarketKind, Record<string, MarketSelection>> = {
    TotalGoals: {
        over: 'Over', peste: 'Over', o: 'Over', plus: 'Over',
        under: 'Under', sub: 'Under', u: 'Under', minus: 'Under',
    },
    NextGoal: {
        home: 'NextGoalHome', gazde: 'NextGoalHome', '1': 'NextGoalHome', nextgoalhome: 'NextGoalHome',
        away: 'NextGoalAway', oaspeti: 'NextGoalAway', '2': 'NextGoalAway', nextgoalaway: 'NextGoalAway',
        none: 'NextGoalNone', niciun: 'NextGoalNone', nogoal: 'NextGoalNone', '0': 'NextGoalNone',
        nextgoalnone: 'NextGoalNone',
    },
    BothTeamsToScore: {
        yes: 'Yes', da: 'Yes', gg: 'Yes',
        no: 'No', nu: 'No', ng: 'No',
    },
    Moneyline1X2: {
        home: 'Home', gazde: 'Home', '1': 'Home',
        draw: 'Draw', egal: 'Draw', remiza: 'Draw', x: 'Draw',
        away: 'Away', oaspeti: 'Away', '2': 'Away',
    },
    Handicap: {
        home: 'HandicapHome', gazde: 'HandicapHome', '1': 'HandicapHome', handicaphome: 'HandicapHome',
        away: 'HandicapAway', oaspeti: 'HandicapAway', '2': 'HandicapAway', handicapaway: 'HandicapAway',
    },
};

// --- Parsing ----------------------------------------------------------------

export function parseQuickImport(raw: string): QuickImportResult {
    const source = readJson(raw);

    const market = readMarket(source);
    const config = marketKindConfig(market);
    const selection = readSelection(source, market);

    const odds = readPositiveOdds(source, ['odds', 'decimalOdds', 'cota'], 'odds');
    const siblingOdds = readSiblings(source, config.siblingCount);
    const line = readLine(source, market, config.needsLine);

    const isLive = readIsLive(source);
    const oddsForm: OddsFormState = {
        ...defaultOddsForm(market),
        matchLabel: readText(source, ['match', 'matchLabel', 'meci']) ?? '',
        selection,
        label: readText(source, ['label', 'marketLabel', 'eticheta']) ?? '',
        line: line === null ? '' : String(line),
        decimalOdds: String(odds),
        siblingOdds: siblingOdds.map(String),
    };

    const liveForm: LiveFormState = isLive
        ? {
              ...defaultLiveForm(),
              isLive: true,
              minutePlayed: String(readNumber(source, ['minute', 'minutePlayed', 'min', 'minut'], 'minute', {
                  required: true,
                  min: 1,
                  max: 120,
              })),
              cumulativeXgHome: String(readXg(source, ['xgHome', 'xg_home', 'xgh', 'homeXg'], 'xgHome')),
              cumulativeXgAway: String(readXg(source, ['xgAway', 'xg_away', 'xga', 'awayXg'], 'xgAway')),
              currentGoalsHome: String(readGoals(source, ['goalsHome', 'golHome', 'scoreHome', 'gh'])),
              currentGoalsAway: String(readGoals(source, ['goalsAway', 'golAway', 'scoreAway', 'ga'])),
          }
        : {
              ...defaultLiveForm(),
              isLive: false,
              manualOwnProbability: String(readOwnProbability(source)),
          };

    return {
        odds: oddsForm,
        live: liveForm,
        bankroll: readOptionalBankroll(source),
    };
}

/** The inverse: the current form as the same flat JSON, for saving a setup or sharing one. */
export function toQuickImportJson(
    odds: OddsFormState,
    live: LiveFormState,
    bankroll: number,
): string {
    const config = marketKindConfig(odds.kind);
    const body: Record<string, unknown> = {};

    if (odds.matchLabel) body.match = odds.matchLabel;

    if (live.isLive) {
        body.minute = numberOrNull(live.minutePlayed);
        body.xgHome = numberOrNull(live.cumulativeXgHome);
        body.xgAway = numberOrNull(live.cumulativeXgAway);
        body.goalsHome = numberOrNull(live.currentGoalsHome) ?? 0;
        body.goalsAway = numberOrNull(live.currentGoalsAway) ?? 0;
    } else {
        body.live = false;
        body.ownProbability = numberOrNull(live.manualOwnProbability);
    }

    body.market = odds.kind;
    body.selection = odds.selection;
    if (config.needsLine) body.line = numberOrNull(odds.line);
    if (odds.label) body.label = odds.label;
    body.odds = numberOrNull(odds.decimalOdds);
    body.siblingOdds = odds.siblingOdds.map(numberOrNull);
    body.bankroll = bankroll;

    return JSON.stringify(body, null, 2);
}

// --- Readers ----------------------------------------------------------------

function readJson(raw: string): Record<string, unknown> {
    const trimmed = raw.trim();
    if (trimmed === '') {
        throw new QuickImportError('Nothing to import — paste a JSON object first.');
    }

    let parsed: unknown;
    try {
        parsed = JSON.parse(trimmed);
    } catch (e) {
        throw new QuickImportError(
            `That is not valid JSON: ${(e as Error).message}. Every name needs double quotes, and ` +
                'there must be no trailing comma before the closing brace.',
        );
    }

    if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
        throw new QuickImportError('Expected a JSON object, like { "market": "TotalGoals", ... }.');
    }

    // Keys are matched case-insensitively and without separators, so "xg_home", "xgHome" and
    // "XG Home" all land on the same field.
    const normalised: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(parsed as Record<string, unknown>)) {
        normalised[normaliseKey(key)] = value;
    }
    return normalised;
}

const normaliseKey = (key: string) => key.toLowerCase().replace(/[\s_-]/g, '');

const normaliseValue = (value: string) => value.toLowerCase().replace(/[\s_-]/g, '');

function pick(source: Record<string, unknown>, names: string[]): unknown {
    for (const name of names) {
        const value = source[normaliseKey(name)];
        if (value !== undefined && value !== null) return value;
    }
    return undefined;
}

function readMarket(source: Record<string, unknown>): MarketKind {
    const raw = pick(source, ['market', 'kind', 'marketKind', 'piata']);
    if (raw === undefined) {
        throw new QuickImportError(
            `"market" is required. Use one of: ${MARKET_KINDS.map((m) => m.kind).join(', ')}.`,
        );
    }

    if (typeof raw !== 'string') {
        throw new QuickImportError(`"market" must be text, got ${describe(raw)}.`);
    }

    const resolved = MARKET_ALIASES[normaliseValue(raw)];
    if (!resolved) {
        throw new QuickImportError(
            `"market": ${JSON.stringify(raw)} is not a market this app prices. ` +
                `Use one of: ${MARKET_KINDS.map((m) => m.kind).join(', ')}.`,
        );
    }
    return resolved;
}

function readSelection(source: Record<string, unknown>, market: MarketKind): MarketSelection {
    const raw = pick(source, ['selection', 'side', 'parte']);
    if (raw === undefined) {
        throw new QuickImportError(
            `"selection" is required — which side of the market is being priced. For ${market}, one of: ` +
                `${marketKindConfig(market).selections.map((s) => s.value).join(', ')}.`,
        );
    }

    const text = typeof raw === 'number' ? String(raw) : raw;
    if (typeof text !== 'string') {
        throw new QuickImportError(`"selection" must be text, got ${describe(raw)}.`);
    }

    const resolved = SELECTION_ALIASES[market][normaliseValue(text)];
    if (!resolved) {
        throw new QuickImportError(
            `"selection": ${JSON.stringify(text)} does not belong to the ${market} market. ` +
                `Use one of: ${marketKindConfig(market).selections.map((s) => s.value).join(', ')}.`,
        );
    }
    return resolved;
}

function readLine(
    source: Record<string, unknown>,
    market: MarketKind,
    needsLine: boolean,
): number | null {
    const raw = pick(source, ['line', 'linie', 'goalLine', 'handicapLine']);

    if (!needsLine) return null;

    if (raw === undefined) {
        throw new QuickImportError(
            `"line" is required for the ${market} market — e.g. 2.5, or 6.5 for a high total.`,
        );
    }

    const value = toNumber(raw);
    if (value === null) {
        throw new QuickImportError(`"line" must be a number, got ${describe(raw)}.`);
    }
    return value;
}

function readPositiveOdds(
    source: Record<string, unknown>,
    names: string[],
    label: string,
): number {
    const raw = pick(source, names);
    if (raw === undefined) {
        throw new QuickImportError(`"${label}" is required — the decimal price you can actually get.`);
    }

    const value = toNumber(raw);
    if (value === null) {
        throw new QuickImportError(`"${label}" must be a number, got ${describe(raw)}.`);
    }
    if (value <= 1) {
        throw new QuickImportError(
            `"${label}" must be greater than 1.0, got ${value}. These are decimal odds (1.91), not ` +
                'fractional or American.',
        );
    }
    return value;
}

function readSiblings(source: Record<string, unknown>, expected: number): number[] {
    const raw = pick(source, ['siblingOdds', 'otherOdds', 'siblings', 'celelalteCote']);
    if (raw === undefined) {
        throw new QuickImportError(
            `"siblingOdds" is required: ${expected === 1 ? 'the other price' : `the other ${expected} prices`} ` +
                'in the same market. Without them the bookmaker margin cannot be removed.',
        );
    }

    // A two-way market has a single sibling, so accepting a bare number saves a pair of brackets.
    const list = Array.isArray(raw) ? raw : [raw];

    const values = list.map((entry, index) => {
        const value = toNumber(entry);
        if (value === null) {
            throw new QuickImportError(
                `"siblingOdds" entry ${index + 1} must be a number, got ${describe(entry)}.`,
            );
        }
        if (value <= 1) {
            throw new QuickImportError(
                `"siblingOdds" entry ${index + 1} must be greater than 1.0, got ${value}.`,
            );
        }
        return value;
    });

    if (values.length !== expected) {
        throw new QuickImportError(
            `"siblingOdds" needs exactly ${expected} ${expected === 1 ? 'price' : 'prices'} for this ` +
                `market, got ${values.length}. Every outcome in the market has to be there for the de-vig ` +
                'to mean anything.',
        );
    }
    return values;
}

function readIsLive(source: Record<string, unknown>): boolean {
    const raw = pick(source, ['live', 'isLive', 'inPlay']);
    if (typeof raw === 'boolean') return raw;
    if (typeof raw === 'string') return normaliseValue(raw) !== 'false';

    // Unstated: a minute on the clock means the match is running.
    const preMatch = pick(source, ['isPreMatch', 'preMatch']);
    if (preMatch === true) return false;
    return pick(source, ['minute', 'minutePlayed', 'min', 'minut']) !== undefined;
}

function readNumber(
    source: Record<string, unknown>,
    names: string[],
    label: string,
    bounds: { required?: boolean; min?: number; max?: number },
): number {
    const raw = pick(source, names);
    if (raw === undefined) {
        if (!bounds.required) return 0;
        throw new QuickImportError(`"${label}" is required for a live match.`);
    }

    const value = toNumber(raw);
    if (value === null) {
        throw new QuickImportError(`"${label}" must be a number, got ${describe(raw)}.`);
    }
    if (bounds.min !== undefined && value < bounds.min) {
        throw new QuickImportError(`"${label}" must be at least ${bounds.min}, got ${value}.`);
    }
    if (bounds.max !== undefined && value > bounds.max) {
        throw new QuickImportError(`"${label}" must be at most ${bounds.max}, got ${value}.`);
    }
    return value;
}

function readXg(source: Record<string, unknown>, names: string[], label: string): number {
    const raw = pick(source, names);
    if (raw === undefined) {
        throw new QuickImportError(
            `"${label}" is required for a live match — the cumulative xG from the stats screen.`,
        );
    }

    const value = toNumber(raw);
    if (value === null) {
        throw new QuickImportError(`"${label}" must be a number, got ${describe(raw)}.`);
    }
    if (value < 0) {
        throw new QuickImportError(`"${label}" cannot be negative, got ${value}.`);
    }
    return value;
}

function readGoals(source: Record<string, unknown>, names: string[]): number {
    const raw = pick(source, names);
    if (raw === undefined) return 0;

    const value = toNumber(raw);
    if (value === null || value < 0 || !Number.isInteger(value)) {
        throw new QuickImportError(`Goals must be a whole number of 0 or more, got ${describe(raw)}.`);
    }
    return value;
}

function readOwnProbability(source: Record<string, unknown>): number {
    const raw = pick(source, ['ownProbability', 'probability', 'probabilitate', 'myProbability']);
    if (raw === undefined) {
        throw new QuickImportError(
            'A pre-match analysis has no live xG to work from, so "ownProbability" is required — your ' +
                'own estimate, as a percentage (62) or a fraction (0.62).',
        );
    }

    const value = toNumber(raw);
    if (value === null) {
        throw new QuickImportError(`"ownProbability" must be a number, got ${describe(raw)}.`);
    }
    if (value < 0 || value > 100) {
        throw new QuickImportError(`"ownProbability" must be between 0 and 100, got ${value}.`);
    }

    // The form field is a percentage. A value at or below 1 is read as a fraction, which makes 0.62
    // and 62 both mean the same thing — and makes a probability of exactly 1% unreachable this way,
    // which is a price nobody is analysing.
    return value <= 1 ? value * 100 : value;
}

function readOptionalBankroll(source: Record<string, unknown>): number | null {
    const raw = pick(source, ['bankroll', 'banca', 'buget']);
    if (raw === undefined) return null;

    const value = toNumber(raw);
    if (value === null || value < 0) {
        throw new QuickImportError(`"bankroll" must be a number of 0 or more, got ${describe(raw)}.`);
    }
    return value;
}

function readText(source: Record<string, unknown>, names: string[]): string | null {
    const raw = pick(source, names);
    return typeof raw === 'string' && raw.trim() !== '' ? raw.trim() : null;
}

// --- Helpers ----------------------------------------------------------------

/** Accepts numbers and numeric strings, including the comma decimals a Romanian keyboard produces. */
function toNumber(raw: unknown): number | null {
    if (typeof raw === 'number') return Number.isFinite(raw) ? raw : null;
    if (typeof raw !== 'string') return null;

    const cleaned = raw.trim().replace(',', '.');
    if (cleaned === '') return null;

    const value = Number(cleaned);
    return Number.isFinite(value) ? value : null;
}

function numberOrNull(raw: string): number | null {
    const value = toNumber(raw);
    return value;
}

function describe(raw: unknown): string {
    if (raw === null) return 'null';
    if (Array.isArray(raw)) return 'a list';
    return typeof raw === 'object' ? 'an object' : JSON.stringify(raw);
}
